d"]=[[rlt_20zqtext2]]},["rlt_20zqtext20"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL韩千叶：方才交手在下获益良多，阁下可愿再赐教一番？]],["id"]=[[rlt_20zqtext20]]},["rlt_20zqtext21"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL叶妄生：我行走江湖只有一个原则：不相信任何人。]],["id"]=[[rlt_20zqtext21]]},["rlt_20zqtext22"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL叶妄生：你竟能胜我？想是我近些日子疏于练武了。罢了，这东西便赠给你作中秋彩头吧。]],["id"]=[[rlt_20zqtext22]]},["rlt_20zqtext23"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL叶妄生：败在我的手下，不丢人。]],["id"]=[[rlt_20zqtext23]]},["rlt_20zqtext24"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL叶妄生：你我再斗一次，我未必输你！]],["id"]=[[rlt_20zqtext24]]},["rlt_20zqtext25"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL凌风：“儒以文乱法，侠以武犯禁。”唯有律法约束，万事万物方可循规运转，此为律法存在之要义。]],["id"]=[[rlt_20zqtext25]]},["rlt_20zqtext26"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL凤四娘：他若是在此，我定要亲手做月饼给他吃。]],["id"]=[[rlt_20zqtext26]]},["rlt_20zqtext27"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL张公子：我余生所愿，便是和敏敏隐退江湖，远离这江湖上的一切恩恩怨怨。]],["id"]=[[rlt_20zqtext27]]},["rlt_20zqtext28"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL叶妄生：这世上的好人，我一只手便能数过来。]],["id"]=[[rlt_20zqtext28]]},["rlt_20zqtext3"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL凌风：少侠想要胜我，只怕还要多钻研几日武功。]],["id"]=[[rlt_20zqtext3]]},["rlt_20zqtext4"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL凌风：方才交手未能尽兴，还望少侠再指教两招。]],["id"]=[[rlt_20zqtext4]]},["rlt_20zqtext5"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL凤四娘：便是追到天涯海角，我也要找到他。]],["id"]=[[rlt_20zqtext5]]},["rlt_20zqtext6"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL凤四娘：阁下好功夫，此番交手痛快！痛快！这东西便赠给你吧。]],["id"]=[[rlt_20zqtext6]]},["rlt_20zqtext7"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL凤四娘：你武功不错，若是再加磨练或能与我比肩。]],["id"]=[[rlt_20zqtext7]]},["rlt_20zqtext8"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL凤四娘：你我再比划两下？我还有几招绝技未用。]],["id"]=[[rlt_20zqtext8]]},["rlt_20zqtext9"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL张公子：我娘说过不要相信漂亮女人，这话说得太过绝对了，人心无常，岂是仅凭容貌就能断定的。]],["id"]=[[rlt_20zqtext9]]},["rlt_20zqtsnpctf1"]={["arg1"]=[[随机人物投放]],["arg2"]=[[20zhongqiunpc1]],["arg3"]=[[fb213_22;fb213_27;fb213_02;fb213_07;fb213_05;fb213_24]],["id"]=[[rlt_20zqtsnpctf1]]},["rlt_20zqtsnpctf2"]={["arg1"]=[[随机人物投放]],["arg2"]=[[20zhongqiunpc2]],["arg3"]=[[fb213_22